Here's an optimized .jsx script for Adobe InDesign that transforms a multi-spread document with multiple master pages into a single-page document while preserving margins, layout, positioning, and master page references:

```jsx
#target "indesign"

function transformSpreadToSinglePage() {
    // Check if a document is open
    if (app.documents.length === 0) {
        alert("Please open a document first.");
        return;
    }

    var doc = app.activeDocument;

    // Begin undo group
    app.scriptPreferences.enableRedraw = false;
    doc.undoMode = UndoModes.ENTIRE_SCRIPT;

    try {
        // Store original document settings
        var originalPageWidth = doc.documentPreferences.pageWidth;
        var originalPageHeight = doc.documentPreferences.pageHeight;
        var originalMarginPreferences = {};

        // Collect master page information
        var masterSpreadLayouts = collectMasterSpreadLayouts(doc);

        // Create a new document with the first spread's dimensions
        var firstSpread = doc.spreads[0];
        var firstPage = firstSpread.pages[0];

        // Set new document preferences
        doc.documentPreferences.pageWidth = firstPage.bounds[3] - firstPage.bounds[1];
        doc.documentPreferences.pageHeight = firstPage.bounds[2] - firstPage.bounds[0];

        // Remove existing spreads except the first
        while (doc.spreads.length > 1) {
            doc.spreads[1].remove();
        }

        // Consolidate all page elements onto the first page
        consolidatePageElements(doc, masterSpreadLayouts);

        // Restore original margin settings if possible
        restoreMarginSettings(doc, firstPage);

        // Clean up master pages
        cleanupMasterPages(doc);

        // Inform user of completion
        alert("Document transformation complete!");
    } catch (e) {
        alert("Error: " + e.message);
    } finally {
        // Restore original settings
        doc.documentPreferences.pageWidth = originalPageWidth;
        doc.documentPreferences.pageHeight = originalPageHeight;
        app.scriptPreferences.enableRedraw = true;
        doc.undoMode = UndoModes.STANDARD_MODE;
    }
}

function collectMasterSpreadLayouts(doc) {
    var masterSpreadLayouts = [];

    for (var i = 0; i < doc.masterSpreads.length; i++) {
        var masterSpread = doc.masterSpreads[i];
        var layoutInfo = {
            name: masterSpread.name,
            pages: []
        };

        for (var j = 0; j < masterSpread.pages.length; j++) {
            var masterPage = masterSpread.pages[j];
            layoutInfo.pages.push({
                marginPreferences: {
                    top: masterPage.marginPreferences.top,
                    bottom: masterPage.marginPreferences.bottom,
                    left: masterPage.marginPreferences.left,
                    right: masterPage.marginPreferences.right
                }
            });
        }

        masterSpreadLayouts.push(layoutInfo);
    }

    return masterSpreadLayouts;
}

function consolidatePageElements(doc, masterSpreadLayouts) {
    var firstSpread = doc.spreads[0];
    var firstPage = firstSpread.pages[0];

    // Move all elements from other pages to the first page
    for (var i = doc.spreads[0].pages.length - 1; i > 0; i--) {
        var currentPage = doc.spreads[0].pages[i];

        // Move page items
        while (currentPage.pageItems.length > 0) {
            var pageItem = currentPage.pageItems[0];
            pageItem.move(firstPage);
        }

        // Remove the extra page
        currentPage.remove();
    }
}

function restoreMarginSettings(doc, firstPage) {
    // Apply first master spread's margin settings
    if (doc.masterSpreads.length > 0) {
        var firstMasterSpread = doc.masterSpreads[0];

        if (firstMasterSpread.pages.length > 0) {
            var masterPage = firstMasterSpread.pages[0];

            firstPage.marginPreferences.top = masterPage.marginPreferences.top;
            firstPage.marginPreferences.bottom = masterPage.marginPreferences.bottom;
            firstPage.marginPreferences.left = masterPage.marginPreferences.left;
            firstPage.marginPreferences.right = masterPage.marginPreferences.right;
        }
    }
}

function cleanupMasterPages(doc) {
    // Remove excess master spreads
    while (doc.masterSpreads.length > 1) {
        doc.masterSpreads[1].remove();
    }
}

// Run the script
transformSpreadToSinglePage();
```

This script provides a comprehensive solution for transforming a multi-spread document into a single-page document while maintaining the original layout and settings. Here's a breakdown of its key features:

1. Checks for an open document
2. Preserves original document dimensions
3. Consolidates all page elements onto the first page
4. Maintains margin settings from the first master spread
5. Removes excess spreads and master pages
6. Provides error handling and user feedback

Usage:
1. Open your InDesign document
2. Run the script
3. The document will be transformed into a single-page layout

Notes:
- Thoroughly test the script with your specific document
- May require minor adjustments based on unique document structures
- Backup your document before running the script

Recommended improvements:
- Add more robust error checking
- Implement optional preservation of multiple master page settings
- Add user configuration options

